def hp_filter(y, lamb=100):
    n = len(y)
    I = [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    D = [[0] * n for _ in range(n-2)]
    for i in range(n-2):
        D[i][i] = 1
        D[i][i+1] = -2
        D[i][i+2] = 1

    lhs = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            lhs[i][j] = I[i][j]
            for k in range(n-2):
                lhs[i][j] += lamb * D[k][i] * D[k][j]

    tau = [0] * n
    for i in range(n):
        for j in range(n):
            tau[i] += lhs[i][j] * y[j]

    return tau
